     * doar în submeniul care rămâne; submeniul rămâne ⇔ are ≥ 1 frunză DA sau e numai din frunze NEUTRE (poziție fără țintă,
     * ex. canalul cu vederi «(în lucru)»); submeniul ale cărui frunze cu țintă sunt toate NU dispare (02a §4: «Configurare»).
     * Reconstruirea doar prin {@code cuCopii} (păstrează câmpurile nodului, G-22 / K-29).
     */
    private static PeRol filtreaza(Item nod, java.util.function.Function<String, Drept> drept, java.util.Set<String> dubluri) {
        if (nod.isLeaf()) {
            Drept d = nod.targetMenu == null ? Drept.NEUTRU : drept.apply(nod.targetMenu);
            if (d == Drept.DA)
                return new PeRol(nod, 1, dubluri.contains(nod.targetMenu) ? 0 : 1, 0);
            if (d == Drept.NEUTRU)
                return new PeRol(nod, 0, 0, 0);
            return new PeRol(null, 0, 0, 1);
        }
        java.util.List<Item> copii = new java.util.ArrayList<>();
        int da = 0, daNeDublura = 0, nu = 0;
        boolean schimbat = false;
        for (Item c : nod.children) {
            PeRol f = filtreaza(c, drept, dubluri);
            da += f.da;
            daNeDublura += f.daNeDublura;
            nu += f.nu;
            schimbat |= f.nod != c;
            if (f.nod != null)
                copii.add(f.nod);
        }
        boolean ramane = da > 0 || (nu == 0 && !copii.isEmpty());
        if (!ramane)
            return new PeRol(null, da, daNeDublura, nu);
        return new PeRol(schimbat ? nod.cuCopii(copii.toArray(new Item[0])) : nod, da, daNeDublura, nu);
    }

