     */
    static List<Rand> comparaParteneri(Map<String, BigDecimal> saga, Map<String, EvaPartener> activi, boolean client,
            Set<String> inactivi, BigDecimal tol) {
        Set<String> chei = new TreeSet<>(saga.keySet());
        for (EvaPartener p : activi.values())
            if (sold(p, client).signum() != 0)
                chei.add(p.value());
        List<Rand> out = new ArrayList<>();
        for (String k : chei) {
            BigDecimal s = saga.get(k);
            EvaPartener p = activi.get(k);
            BigDecimal e = p == null ? null : sold(p, client);
            String nume = p == null ? "" : p.nume();
            if (s == null) {
                if (e.signum() != 0)
                    out.add(new Rand(k, nume, null, null, e, null, Stare.DOAR_EVA));
                continue;
            }
            if (p == null) {
                if (s.signum() == 0)
                    continue;
                out.add(new Rand(k, nume, null, s, null, null, inactivi.contains(k) ? Stare.INACTIV : Stare.DOAR_SAGA));
                continue;
            }
            if (s.signum() == 0 && e.signum() == 0)
                continue;
            BigDecimal dl = delta(s, e);
            out.add(new Rand(k, nume, null, s, e, dl, concordant(dl, tol) ? Stare.CONCORDANT : Stare.DIFERENTA));
        }
        return out;
    }

