def inject_i18n():
    """Pune `lang`, `t(key)` și metadatele de limbă la dispoziția tuturor template-urilor.
    `t` e o funcție: în Jinja se folosește ca {{ t('cheie') }}.
    Aditiv: nu suprascrie variabilele deja pasate explicit la render_template."""
    lang = eva_pick_lang()
    # `area` = zona curentă (administrare vs operare) pentru evidențierea tab-ului din topbar.
    try:
        path = request.path or ""
    except Exception:  # noqa: BLE001
        path = ""
    if path.startswith("/app/admin"):
        area = "admin"
    elif path.startswith("/app/remote"):
        area = "remote"
    elif path.startswith("/app/cont"):
        area = "cont"
    else:
        area = "operare"
    try:
        cur_cui = (request.cookies.get("eva_cui") or "").strip() or DEFAULT_TENANT
    except Exception:  # noqa: BLE001
        cur_cui = DEFAULT_TENANT
    # Denumirea firmei active — calculată doar pe paginile portalului (/app), ca să nu
    # adăugăm apeluri pe storefront-ul public. Cache 60s în _firm_name.
    cur_name = cur_cui
    cabinet_name = cabinet_cui = None
    if path.startswith("/app"):
        try:
            cur_name = _firm_name(cur_cui)
        except Exception:  # noqa: BLE001
            cur_name = cur_cui
        try:
            cabinet_cui, cabinet_name = _cabinet_info()
        except Exception:  # noqa: BLE001
            cabinet_cui = cabinet_name = None
    try:  # T32 L6k (D-2): bannerul comun «nicio firmă activă», pus de garda `firma_activa(blocheaza=False)`
        fara_firma = bool(getattr(g, "eva_fara_firma", False))
    except RuntimeError:   # în afara unui context de aplicație: fără banner
        fara_firma = False
    return {
        "eva_fara_firma": fara_firma,
        "lang": lang,
        "t": lambda key: eva_i18n.t(key, lang),
        "eva_langs": EVA_LANGS,
        "lang_labels": eva_i18n.LANG_LABELS,
        "lang_names": eva_i18n.LANG_NAMES,


