import pathlib,json,hashlib,datetime,collections
p=pathlib.Path(__file__).parent;ex=p.parent;r=ex.parent
f=ex/'A09_raport.json';report=json.loads(f.read_text(encoding='utf8'));plan=json.loads((r/'A09_plan.json').read_text(encoding='utf8'))
e={a['evidence_id']:a for a in report['evidence_index']}
for a in e.values():
 raw=(r/a['path']).read_bytes()
 assert hashlib.sha256(raw).hexdigest()==a['sha256'],a['path']
for c in report['controls']:
 assert set(c['evidence_ids'])<=e.keys()
 assert c['observed'] and c['remaining_or_retest']; assert c['control_id'] in [j['id'] for j in plan['controls']]
for v in report['findings']:
 v['status']='CONFIRMAT';v['A11_decision']=None
 for k in ('observed_fact','preconditions','reproduction'):v[k]=v[k].replace('Cinco','Cinci')
for id in ('A09-C01','A09-C08','A09-C13','A09-C26'):
 c=next(a for a in report['controls'] if a['control_id']==id);c['status']='INCONCLUDENT'
for v in report['controls']:
 v['observed']=v['observed'].replace('a respondit','a răspuns').replace('Source labels','Etichetele sursă')
for v in report['pipelines']:
 cc=[i for i in report['controls'] if i['pipeline']==v['pipeline_id']]; v['coverage_by_status']=dict(collections.Counter(c['status'] for c in cc))
 v['observed_per_stage']=[{'control':c['control_id'],'observed':c['observed'],'remaining':c['remaining_or_retest']} for c in cc]
 v['status']='FAIL_DOVEDIT' if any(c['status']=='FAIL_DOVEDIT' for c in cc) else 'BLOCAT_ACCES' if all(c['status']=='BLOCAT_ACCES' for c in cc) else 'INCONCLUDENT'
report['counts']['by_status']=dict(collections.Counter(c['status'] for c in report['controls']))
report['limits'][1]=report['limits'][1].replace('accesibiliate','accesibilitate')
fr=p/'fise';fr.mkdir(exist_ok=True);sheets=[]
for unit in report['controls']+report['pipelines']:
 id=unit.get('control_id') or unit['pipeline_id']
 card={'id':id,'results':unit,'source_and_raw_evidence':[e[a] for a in unit['evidence_ids']],'checklist':next((c for c in plan['controls']+plan['pipelines'] if c['id']==id),{}),'limits':'Numai probele indicate au fost executate. Starea și pașii deschiși sunt prevăzuți în rezultate.'}
 path=fr/(id+'.json');path.write_text(json.dumps(card,ensure_ascii=False,indent=2)+'\\n',encoding='utf8');sheets.append({'id':id,'path':path.relative_to(r).as_posix(),'sha256':hashlib.sha256(path.read_bytes()).hexdigest()})
assert len(sheets)==36;report['individual_sheets']=sheets
f.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\\n',encoding='utf8')
print(report['counts'],hashlib.sha256(f.read_bytes()).hexdigest())

