 * după un rezultat definitiv, după «Reîncarc»), ACEEAȘI la «Reîncerc» după fără legătură / 5xx cu corpul identic;
 * o singură cerere în zbor (a doua apăsare ⇒ ignorată). Nimic nu se trimite singur: reîncercarea doar la apăsare (R-336-38).
 */
class ScriereIdempotenta<C>(private val cheieNoua: () -> String = { IdentificatorDispozitiv.cheieNoua() }) {
    private var corp: C? = null
    private var cheie: String? = null
    private var inZbor = false

    /** Ultimul rezultat a fost fără legătură / eroare de server ⇒ «Reîncerc» (aceeași cheie, același corp). */
    var deReincercat = false
        private set

    /** Cheia pentru trimiterea lui [c]; `null` = o cerere e deja în zbor (dublu-clic ⇒ 1 POST). */
    @Synchronized
    fun incepe(c: C): String? {
        if (inZbor) return null
        if (cheie == null || c != corp) {
            cheie = cheieNoua()
            corp = c
        }
        inZbor = true
