class AnteteEva(baza: HttpUrl, private val dispozitiv: String, private val versiune: Int) : Interceptor {
    private val prefix = baza.encodedPath + Cai.PREFIX_V1

    override fun intercept(chain: Interceptor.Chain): Response {
        val cerere = chain.request()
        if (!cerere.url.encodedPath.startsWith(prefix)) return chain.proceed(cerere)
        return chain.proceed(
            cerere.newBuilder()
                .header(ApiEvaMobil.ANTET_VERSIUNE, versiune.toString())
                .header(ApiEvaMobil.ANTET_DISPOZITIV, dispozitiv)
                .build(),
        )
    }
}

