/**
 * Fereastra „Preview site”: iframe catre magazinul public, same-origin
 * (nginx serveste si `/` si `/admin/`), cu selectoare de limba, tema si
 * latime de dispozitiv.
 *
 * Tema: porneste pe tema EFECTIVA (`theme_effective` din `GET /settings`). O alta tema se
 * previzualizeaza DOAR prin link-ul semnat (`GET /settings/theme-preview-link`): serverul pune
 * cookie-ul `eva_preview` in browserul adminului (60 min), clientii nu sunt afectati. La
 * revenirea pe tema efectiva si la inchiderea ferestrei se apeleaza `/preview/exit`, care
 * sterge cookie-ul (altfel adminul ar vedea tema previzualizata navigand pe site).
 *
 * Reincarcarea se poate declansa si din afara, prin evenimentul global
 * `cesiro:preview-invalidate` (emis de ecranele de editare dupa o salvare).
 */
import { useQuery } from '@tanstack/react-query';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import * as settingsApi from '../api/settings';
import { tr } from '../lib/format';

const LANGS = ['ro', 'en', 'de', 'hu', 'bg', 'el'] as const;

/* Temele vin din registrul serverului (`GET /themes`); lista hardcodata de dinainte
   se desincroniza la fiecare tema noua. `marketplace_pro` ramane rezerva (fara `/settings`). */
const FALLBACK_THEME = 'marketplace_pro';

const DEVICES = [
  { id: 'desktop', width: 0 },
  { id: 'tablet', width: 834 },
  { id: 'phone', width: 390 },
] as const;

type DeviceId = (typeof DEVICES)[number]['id'];

export const PREVIEW_INVALIDATE_EVENT = 'cesiro:preview-invalidate';

/** De apelat din orice ecran, dupa o salvare reusita. */
export function invalidatePreview(): void {
  window.dispatchEvent(new CustomEvent(PREVIEW_INVALIDATE_EVENT));
}

/** Calea relativa (acelasi origin cu adminul) + `lang`: `https://site/?preview=x` → `/?preview=x&lang=en`. */
function withLang(url: string, lang: string): string {
  const parsed = new URL(url, window.location.origin);
  parsed.searchParams.set('lang', lang);
  return `${parsed.pathname}${parsed.search}`;
}

/** Sterge cookie-ul de previzualizare din browserul adminului (fara sa astepte raspunsul). */
function exitPreviewCookie(): void {
  try {
    void fetch('/preview/exit', { credentials: 'include', redirect: 'manual', keepalive: true, cache: 'no-store' });
  } catch {
    /* ignorat intentionat */
  }
}

export function PreviewApp() {
  const { t, i18n } = useTranslation();
  const [lang, setLang] = useState<string>('ro');
  const [picked, setPicked] = useState<string | null>(null);
  const { data: themes } = useQuery({ queryKey: ['themes'], queryFn: settingsApi.listThemes });
  const { data: settings } = useQuery({ queryKey: ['settings'], queryFn: settingsApi.getSettings });
  const effective = settings?.theme_effective?.theme_id || FALLBACK_THEME;
  const theme = picked ?? effective;
  const isEffective = theme === effective;
  const effectiveSuffix = settings?.theme_mode === 'auto' ? t('shell.preview.themeAuto') : t('shell.preview.themeManual');

  const themeOptions = (themes ?? []).map((item) => {
    // `name` poate fi text simplu sau obiect multilingv, in functie de tema.
    const name = (typeof item.name === 'string' ? item.name : tr(item.name, i18n.language)) || item.id;
    return { id: item.id, label: item.id === effective ? `${name} ${effectiveSuffix}` : name };
  });
  if (!themeOptions.some((o) => o.id === effective)) themeOptions.unshift({ id: effective, label: `${effective} ${effectiveSuffix}` });

  const [device, setDevice] = useState<DeviceId>('desktop');
  const [nonce, setNonce] = useState<number>(() => Date.now());
  /* Cookie-ul `eva_preview` a fost pus (o tema ne-efectiva a fost incarcata) → la revenire se sterge. */
  const previewUsed = useRef(false);
  /* Prima incarcare trece prin `/preview/exit`: fereastra porneste garantat pe tema efectiva,
     chiar daca browserul avea deja un cookie de previzualizare dintr-un tab anterior. */
  const [needsExit, setNeedsExit] = useState(true);

  /* Link-ul semnat se refoloseste cat e valabil (60 min); „Reincarca” cere altul doar daca a expirat. */
  const link = useQuery({
    queryKey: ['theme-preview-link', theme],
    queryFn: () => settingsApi.getThemePreviewLink(theme),
    enabled: !isEffective,
    staleTime: 55 * 60_000,
    gcTime: 60 * 60_000,
    retry: false,
  });
  const linkExpired = (expiresAt: string | undefined) => !expiresAt || Date.parse(expiresAt) - Date.now() < 60_000;

  const { data: linkData, refetch: refetchLink } = link;
  const reload = useCallback(() => {
    if (!isEffective && linkExpired(linkData?.expires_at)) void refetchLink();
    setNonce(Date.now());
  }, [isEffective, linkData?.expires_at, refetchLink]);

  useEffect(() => {
    window.addEventListener(PREVIEW_INVALIDATE_EVENT, reload);
    return () => window.removeEventListener(PREVIEW_INVALIDATE_EVENT, reload);
  }, [reload]);

  /* Inchiderea ferestrei: nu lasam cookie-ul de previzualizare in browser. */
  useEffect(() => () => { if (previewUsed.current) exitPreviewCookie(); }, []);

  const chooseTheme = (id: string) => {
    if (id === effective && previewUsed.current) setNeedsExit(true);
    setPicked(id);
  };

  const src = useMemo(() => {
    if (needsExit) return '/preview/exit';
    if (!isEffective) return linkData ? withLang(linkData.url, lang) : null;
    const params = new URLSearchParams({ lang, _ts: String(nonce) });
    return `/?${params.toString()}`;
  }, [isEffective, linkData, lang, nonce, needsExit]);

  useEffect(() => { if (!isEffective && linkData) previewUsed.current = true; }, [isEffective, linkData]);

  /* `/preview/exit` a sters cookie-ul (si a redirectat la `/`): reincarcam in limba aleasa. */
  const onFrameLoad = () => {
    if (!needsExit) return;
    previewUsed.current = false;
    setNeedsExit(false);
  };

  const frameWidth = DEVICES.find((d) => d.id === device)?.width ?? 0;

  return (
    <div className="os-preview">
      <div className="os-preview__bar">
        <label className="os-preview__field">
          <span>{t('app.language')}</span>
          <select value={lang} onChange={(e) => setLang(e.target.value)} data-testid="preview-lang">
            {LANGS.map((code) => (
              <option key={code} value={code}>
                {code.toUpperCase()}
              </option>
            ))}
          </select>
        </label>

        <label className="os-preview__field">
          <span>{t('nav.appearance')}</span>
          <select value={theme} onChange={(e) => chooseTheme(e.target.value)} data-testid="preview-theme">
            {themeOptions.map(({ id, label }) => (
              <option key={id} value={id}>
                {label}
              </option>
            ))}
          </select>
        </label>

        <div className="os-preview__devices" role="group" aria-label={t('shell.preview.device')}>
          {DEVICES.map((d) => (
            <button
              key={d.id}
              type="button"
              className={d.id === device ? 'is-active' : undefined}
              onClick={() => setDevice(d.id)}
            >
              {t(`shell.preview.${d.id}`)}
            </button>
          ))}
        </div>

        <button type="button" className="os-preview__reload" onClick={reload}>
          {t('actions.refresh')}
        </button>
        <a className="os-preview__external" href={src && !needsExit ? src : `/?lang=${lang}`} target="_blank" rel="noreferrer" data-testid="preview-open-tab">
          {t('shell.preview.openTab')}
        </a>
      </div>
      <p className="os-preview__hint" data-testid="preview-hint">
        {isEffective ? t('shell.preview.hintEffective') : t('shell.preview.hint')}
      </p>
      {link.isError && <p className="os-preview__hint os-preview__hint--error" role="alert">{t('common.error')}</p>}

      <div className="os-preview__stage">
        {src && (
          <iframe
            key={`${src}|${nonce}`}
            className="os-preview__frame"
            style={frameWidth > 0 ? { width: frameWidth } : undefined}
            src={src}
            title={t('nav.preview')}
            data-testid="preview-frame"
            onLoad={onFrameLoad}
            sandbox="allow-same-origin allow-scripts allow-forms allow-popups"
          />
        )}
      </div>
    </div>
  );
}

export default PreviewApp;
