def serializer():
    from itsdangerous import URLSafeTimedSerializer

    secret = _secret()
    if not secret:
        raise RuntimeError("SECRET_KEY lipsește: nu pot semna linkul de previzualizare")
    return URLSafeTimedSerializer(secret, salt=SALT)


def make_token(theme_id: str, tenant_id: str, admin_id: str) -> tuple[str, datetime]:
    """(token, expires_at UTC)."""
    token = serializer().dumps({"theme_id": str(theme_id), "tenant_id": str(tenant_id),
                                "admin_id": str(admin_id or "")})
    return token, datetime.now(timezone.utc) + timedelta(seconds=TTL)


def load_token(token: Any, tenant_id: str | None, *, max_age: int = TTL) -> dict[str, Any] | None:
    """Payload-ul valid pentru `tenant_id`, cu `expires_at` (datetime UTC) — sau None.

    None pentru: token lipsă/prea lung, semnătură greșită, expirat, alt tenant, temă
    necunoscută în registry.
    """
    token = str(token or "").strip()
    if not token or len(token) > 1024 or not tenant_id:
        return None
    try:
        payload, signed_at = serializer().loads(token, max_age=max_age, return_timestamp=True)

